test('Every selected owner rejects unknown/mixed/deleted/duplicated/cache/statement/body drift before historical projections',()=>{for(const[f,r]of Object.entries(contract.files)){const s=read(f);for(const bad of[s+'\n',s.replace('coyote-macroform-5','coyote-macroform-unknown')]){if(bad===s)continue;assert.throws(()=>assert.equal(sha(undoNorthRimSource(bad,f)),r.baselineSHA256));}for(const c of changes.filter(c=>c.file===f)){let currentGroup=c.after;for(const later of changes.slice(changes.indexOf(c)+1).filter(v=>v.file===f)){if(currentGroup.includes(later.before)){assert.equal(currentGroup.split(later.before).length,2);currentGroup=currentGroup.replace(later.before,later.after);}}assert.equal(s.split(currentGroup).length,2,'Deletion fixture identifies the composed current group');assert.throws(()=>assert.equal(sha(undoNorthRimSource(s.replace(currentGroup,''),f)),r.baselineSHA256));assert.throws(()=>assert.equal(sha(undoNorthRimSource(s+'\n'+currentGroup,f)),r.baselineSHA256));}}});
