test('Actual graph uses nine direct cache5 imports and current full feature, photoscan and world caller suffixes',()=>{let direct=0;for(const f of Object.keys(contract.files)){const s=read(f);assert(!s.includes('coyote-macroform-4'));direct+=s.split('\n').filter(l=>l.startsWith('import ')&&l.includes('coyote-macroform-5')&&!l.includes('earned-region-1-coyote')&&!l.includes('programme-club')).length;}assert.equal(direct,9);assert(read('ranch3d.html').includes('mown-course-turf-4-coyote-macroform-5'));assert(read('ranch3d.html').includes('world-photoscans.js?v=coyote-scan-composition-4'));});
test('Pinned two old physical recipe modules are isolated to explicitly historical checks; current model helper body remains exact actualV3',()=>{assert.equal(sha(fs.readFileSync(new URL('historical/assets/canyon-landscape.js',dir))),'56b44ae22f3ca4f1d58cd43182df01947efe934de04e38e5b15575b3c3db33a8');assert.equal(sha(fs.readFileSync(new URL('historical/assets/coyote-macroform.mjs',dir))),'2445c7c60a1c659c1e5258ee9507597c1de4f1406f21105e587b21ee3008d199');assert.equal(sha(read('assets/coyote-macroform.mjs')),contract.helperSHA256);});
